import {
	Component,
	Element,
	Event,
	EventEmitter,
	Host,
	Method,
	Prop,
	State,
	h,
} from "@stencil/core";
import { addConstructedStyle } from "../../utils/browser";
import { getCssRulesForSentimentLink } from "../../utils/sentiments";
import { hasSlot } from "../../utils/slot";

/**
 * @since 0.0.10
 * @status stable
 *
 * @slot - The link's label.
 * @slot prefix - Used to prepend an icon or similar element to the link.
 * @slot suffix - Used to append an icon or similar element to the link.
 *
 * @part base - The component's base wrapper.
 * @part text - The component's base wrapper for the text link.
 * @part error - The component's base wrapper with the error state.
 * @part prefix - The prefix container.
 * @part label - The link's label.
 * @part suffix - The suffix container.
 */

@Component({
	tag: "hbr-link",
	styleUrl: "link.scss",
	shadow: true,
})
export class Link {
	sheet: CSSStyleSheet = new CSSStyleSheet();
	link?: HTMLAnchorElement;

	@Element() host!: HTMLHbrLinkElement;

	@State() hasFocus = false;
	@State() hasLabel = false;
	@State() hasPrefix = false;
	@State() hasSuffix = false;
	@Prop() linkTitle = "";

	/** The link's color scheme. */
	@Prop({ reflect: true }) sentiment:
		| "default"
		| "neutral"
		| "interact"
		| "admin"
		| "success"
		| "warning"
		| "danger"
		| "info" = "interact";

	/** The link styles. */
	@Prop({ reflect: true }) variant: "fill" | "outline" | "text" = "text";

	/** The link's size. */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	/** Set to true to disable the link. */
	@Prop({ reflect: true }) disabled = false;

	/** Set to true to draw a pill-style link with rounded edges. */
	@Prop({ reflect: true }) pill = false;

	/** Set to true to draw a circle link. */
	@Prop({ reflect: true }) circle = false;

	/** Indicates if error state */
	@Prop({ reflect: true }) error = false;

	/** Set to true to make the link inline element. since v2.9.12 */
	@Prop({ reflect: true }) inline = false;

	/** URL of the link. */
	@Prop() href?: string;

	/** Tells the browser where to open the link. */
	@Prop() target?: "_blank" | "_parent" | "_self" | "_top";

	/** Attributes related to screen readers. */
	@Prop() aria: { label?: string } = {};

	/**
	 * When using `href`, this attribute will map to the underlying link's `rel` attribute. Unlike regular links, the
	 * default is `noreferrer noopener` to prevent security exploits. However, if you're using `target` to point to a
	 * specific tab/window, this will prevent that from working correctly. You can remove or change the default value by
	 * setting the attribute to an empty string or a value of your choice, respectively.
	 */
	@Prop() rel = "noreferrer noopener";

	/** Tells the browser to download the linked file as this filename. */
	@Prop() download?: string;

	/** The no padding. */
	@Prop({ reflect: true }) noPadding = false;

	/** Emitted when the link loses focus. */
	@Event({ eventName: "hbr-blur" }) hbrBlur!: EventEmitter<void>;

	/** Emitted when the link gains focus. */
	@Event({ eventName: "hbr-focus" }) hbrFocus!: EventEmitter<void>;

	connectedCallback() {
		this.handleBlur = this.handleBlur.bind(this);
		this.handleFocus = this.handleFocus.bind(this);
		this.handleClick = this.handleClick.bind(this);
		this.handleSlotChange = this.handleSlotChange.bind(this);
	}

	componentWillLoad() {
		this.handleSlotChange();
	}

	/** Sets focus on the link. */
	@Method()
	async setFocus(options?: FocusOptions) {
		this.link?.focus(options);
	}

	/** Removes focus from the link. */
	@Method()
	async removeFocus() {
		this.link?.blur();
	}

	handleSlotChange() {
		this.hasLabel = hasSlot(this.host);
		this.hasPrefix = hasSlot(this.host, "prefix");
		this.hasSuffix = hasSlot(this.host, "suffix");
	}

	handleBlur() {
		this.hasFocus = false;
		this.hbrBlur.emit();
	}

	handleFocus() {
		this.hasFocus = true;
		this.hbrFocus.emit();
	}

	handleClick(event: MouseEvent) {
		if (this.disabled) {
			event.preventDefault();
			event.stopPropagation();
		}
	}

	render() {
		const { size, circle, sentiment, variant, disabled } = this;
		let part = "base";
		if (this.error) part += " error";

		const cls: Record<string, boolean> = {
			link: true,
			// Sizes
			"link--small": size === "small",
			"link--medium": size === "medium",
			"link--large": size === "large",

			// Modifiers
			"link--circle": circle,
			"link--disabled": this.disabled,
			"link--focused": this.hasFocus,
			"link--pill": this.pill,
			"link--text": variant === "text",
			"link--fill": variant === "fill",
			"link--outline": variant === "outline",
			"link--has-label": this.hasLabel,
			"link--has-prefix": this.hasPrefix,
			"link--has-suffix": this.hasSuffix,
			"link--no-padding": this.noPadding,
			"link--inline": this.inline,
		};

		cls[`link--${sentiment}`] = true;

		if (
			sentiment &&
			sentiment !== "interact" &&
			variant &&
			variant !== "text" &&
			this.host
		) {
			/** seems like this is not being used. however we are going to leave as it is for backward compatibility reason. */
			this.sheet.replaceSync(`
				:host {
					${getCssRulesForSentimentLink({ sentiment, disabled, variant })}
				}
			`);
			if (this.host.shadowRoot) {
				addConstructedStyle(this.host.shadowRoot, this.sheet);
			}
		}

		return (
			<Host>
				{/* biome-ignore lint/a11y/useValidAnchor: <explanation> */}
				<a
					part={part}
					class={cls}
					ref={(el) => {
						this.link = el;
					}}
					href={this.href}
					target={this.target}
					download={this.download}
					rel={this.rel}
					onBlur={this.handleBlur}
					onFocus={this.handleFocus}
					onClick={this.handleClick}
					aria-disabled={this.disabled ? "true" : undefined}
					title={
						this
							.linkTitle /* An empty title prevents browser validation tooltips from appearing on hover */
					}
					tabIndex={this.disabled ? -1 : 0}
					aria-label={this.aria?.label}
				>
					<span
						part={this.hasPrefix ? "prefix" : ""}
						class={{ link__prefix: this.hasPrefix }}
					>
						<slot onSlotchange={this.handleSlotChange} name="prefix" />
					</span>
					<span
						part={this.hasLabel ? "label" : ""}
						class={{ link__label: this.hasLabel }}
					>
						<slot onSlotchange={this.handleSlotChange} />
					</span>
					<span
						part={this.hasSuffix ? "suffix" : ""}
						class={{ link__suffix: this.hasSuffix }}
					>
						<slot onSlotchange={this.handleSlotChange} name="suffix" />
					</span>
				</a>
			</Host>
		);
	}
}
